import numpy as np

# Test epochs effect on code
# D=1e9, code mix=1.0, tokens_seen = 1e9.
# pool values: 1e9 (1 epoch), 5e8 (2 epochs), 2.5e8 (4 epochs), 1.25e8 (8 epochs), 5e7 (20 epochs)
for p in [1e9, 5e8, 2.5e8, 1.25e8, 6.25e7]:
    res = []
    for _ in range(3):
        r = call_train(5e7, 1e9, {"web": 0, "code": 1.0, "math": 0, "papers": 0}, pool={"code": p})["result"]
        res.append(r["eval_loss"]["code"])
    print(f"Code pool={p:.2e} (epochs={1e9/p:.1f}): code_loss={np.mean(res):.4f} +/- {np.std(res):.4f}")
"]}

